"use client";
import React from "react";
import { useForm, SubmitHandler } from "react-hook-form";
import { zodResolver } from "@hookform/resolvers/zod";
import * as z from "zod";
import {
  Card,
  CardContent,
  CardDescription,
  CardHeader,
  CardTitle,
} from "@/components/ui/card";
import { Button } from "@/components/ui/button";
import { Input } from "@/components/ui/input";
import { Textarea } from "@/components/ui/textarea";
import { Label } from "@/components/ui/label";
import { Switch } from "@/components/ui/switch";
import {
  Select,
  SelectContent,
  SelectItem,
  SelectTrigger,
  SelectValue,
} from "@/components/ui/select";
import {
  Form,
  FormControl,
  FormDescription,
  FormField,
  FormItem,
  FormLabel,
  FormMessage,
} from "@/components/ui/form";

import { Star, Package, Tag, DollarSign, Image, Sparkles } from "lucide-react";

// Zod schema for product validation
const productSchema = z
  .object({
    name: z
      .string()
      .min(1, "Product name is required")
      .max(100, "Name must be less than 100 characters"),
    originalPrice: z
      .number()
      .min(0.01, "Original price must be greater than 0"),
    discountPrice: z
      .number()
      .min(0, "Discount price must be 0 or greater")
      .optional(),
    description: z
      .string()
      .min(10, "Description must be at least 10 characters")
      .max(500, "Description must be less than 500 characters"),
    image: z.string().url("Please enter a valid image URL"),
    category: z.string().min(1, "Please select a category"),
    rating: z
      .number()
      .min(1, "Rating must be at least 1")
      .max(5, "Rating must be at most 5"),
    isNew: z.boolean(),
    stock: z
      .number()
      .min(0, "Stock must be 0 or greater")
      .int("Stock must be a whole number"),
  })
  .refine(
    (data) => {
      if (data.discountPrice && data.discountPrice >= data.originalPrice) {
        return false;
      }
      return true;
    },
    {
      message: "Discount price must be less than original price",
      path: ["discountPrice"],
    }
  );

type ProductFormData = z.infer<typeof productSchema>;

interface Product {
  id: string;
  name: string;
  originalPrice: number;
  discountPrice: number;
  discountPercentage: number;
  description: string;
  image: string;
  category: string;
  rating: number;
  isNew: boolean;
  stock: number;
}

const categories: string[] = [
  "Accessories",
  "Clothing",
  "Electronics",
  "Home & Garden",
  "Sports & Outdoors",
  "Beauty & Personal Care",
  "Books & Media",
  "Toys & Games",
];

export default function FormOne() {
  const form = useForm<ProductFormData>({
    resolver: zodResolver(productSchema),
    defaultValues: {
      name: "",
      originalPrice: 0,
      discountPrice: undefined,
      description: "",
      image: "",
      category: "",
      rating: 5,
      isNew: false,
      stock: 0,
    },
  });

  const watchedOriginalPrice: number = form.watch("originalPrice");
  const watchedDiscountPrice: number | undefined = form.watch("discountPrice");

  const calculateDiscountPercentage = (
    original: number,
    discount: number | undefined
  ): number => {
    if (!discount || discount >= original) return 0;
    return Math.round(((original - discount) / original) * 100);
  };

  const onSubmit: SubmitHandler<ProductFormData> = (data: ProductFormData) => {
    const discountPercentage = data.discountPrice
      ? calculateDiscountPercentage(data.originalPrice, data.discountPrice)
      : 0;

    const product: Product = {
      id: Math.random().toString(36).substr(2, 9),
      name: data.name,
      originalPrice: data.originalPrice,
      discountPrice: data.discountPrice || data.originalPrice,
      discountPercentage,
      description: data.description,
      image: data.image,
      category: data.category,
      rating: data.rating,
      isNew: data.isNew,
      stock: data.stock,
    };

    console.log(product);
    alert("Product created successfully! Check the console for details.");
  };

  const onCancel = (): void => {
    form.reset();
    // setGeneratedProduct(null);
  };

  return (
    <div className="min-h-screen bg-gradient-to-br from-slate-50 via-white to-slate-100 p-4 md:p-8">
