                              <Switch
                                checked={field.value}
                                onCheckedChange={field.onChange}
                              />
                            </FormControl>
                            <Label className="text-sm text-gray-600">
                              {field.value ? "Yes" : "No"}
                            </Label>
                          </div>
                        </FormItem>
                      )}
                    />
                  </div>

