      <View style={[styles.section, styles.grid]}>
        <View style={styles.col}>
          <Text style={styles.h3}>Bill To</Text>
          <Text style={styles.text}>
            Contact Person: {invoiceData.billToContactPerson}
          </Text>
          <Text style={styles.text}>
            Company Name: {invoiceData.billToCompanyName}
          </Text>
          <Text style={styles.text}>
            Location: {invoiceData.billToLocation}
          </Text>
          <Text style={styles.text}>Phone: {invoiceData.billToPhone}</Text>
        </View>
        <View style={[styles.col, styles.textRight]}>
          <Text style={styles.text}>Prepared by: {invoiceData.preparedBy}</Text>
        </View>
      </View>

      {/* Invoice Due Date */}
      <View style={styles.section}>
        <Text style={styles.text}>
          Invoice Due Date: {invoiceData.invoiceDueDate}
        </Text>
      </View>

      {/* Items Table */}
      <View style={styles.table}>
        {/* Table Header */}
        <View style={[styles.tableRow, styles.tableHeader]}>
          <View style={styles.tableColHeader}>
            <Text>Quantity</Text>
          </View>
          <View style={styles.tableColDescHeader}>
            <Text>Description</Text>
          </View>
          <View style={[styles.tableColHeader, styles.tableCell]}>
            <Text>Unit Price</Text>
          </View>
          <View style={[styles.tableColHeader, styles.tableCellCenter]}>
            <Text>Taxable?</Text>
          </View>
          <View style={[styles.tableColHeader, styles.tableCell]}>
            <Text>Amount</Text>
          </View>
        </View>
        {/* Table Body */}
        {invoiceData.items
          .filter((item) => item.quantity > 0)
          .map((item, index) => (
            <View style={styles.tableRow} key={index}>
              <View style={[styles.tableCol, styles.tableCellCenter]}>
                <Text>{item.quantity}</Text>
              </View>
              <View style={styles.tableColDesc}>
                <Text>{item.description}</Text>
              </View>
              <View style={[styles.tableCol, styles.tableCell]}>
                <Text>${item.unitPrice.toFixed(2)}</Text>
              </View>
              <View style={[styles.tableCol, styles.tableCellCenter]}>
                <Text>{item.taxable ? "Yes" : "No"}</Text>
              </View>
              <View style={[styles.tableCol, styles.tableCell]}>
                <Text>${item.amount.toFixed(2)}</Text>
              </View>
            </View>
          ))}
      </View>

      {/* Totals Section */}
      <View style={styles.totalsSection}>
        <View style={styles.totalsBox}>
          <View style={styles.totalRow}>
            <Text style={styles.totalLabel}>Subtotal</Text>
            <Text style={styles.totalValue}>
              ${invoiceData.subtotal.toFixed(2)}
            </Text>
          </View>
          <View style={styles.totalRow}>
            <Text style={styles.totalLabel}>Tax Rate</Text>
            <Text style={styles.totalValue}>
              {invoiceData.taxRate ? `${invoiceData.taxRate}%` : "-"}
            </Text>
          </View>
          <View style={styles.totalRow}>
            <Text style={styles.totalLabel}>Sales Tax</Text>
            <Text style={styles.totalValue}>
              {invoiceData.salesTax
                ? `$${invoiceData.salesTax.toFixed(2)}`
                : "-"}
            </Text>
          </View>
          <View style={styles.totalRow}>
            <Text style={styles.totalLabel}>Other</Text>
            <Text style={styles.totalValue}>
              {invoiceData.other ? `$${invoiceData.other.toFixed(2)}` : "-"}
            </Text>
          </View>
          <View style={styles.grandTotalRow}>
            <Text style={styles.grandTotalLabel}>TOTAL</Text>
            <Text style={styles.grandTotalValue}>
              ${invoiceData.total.toFixed(2)}
            </Text>
          </View>
        </View>
      </View>

      {/* Footer */}
      <View style={styles.footer}>
        <Text style={styles.footerText}>{invoiceData.contactInfo}</Text>
        <Text style={styles.footerText}>{invoiceData.paymentInfo}</Text>
        <Text style={styles.thankYou}>{invoiceData.thankYouMessage}</Text>
      </View>
    </Page>
  </Document>
);

// --- Main Invoice Component ---
const InvoiceFour: React.FC = () => {
  const [isEditMode, setIsEditMode] = useState(false);
  const [invoiceData, setInvoiceData] =
    useState<InvoiceData>(initialInvoiceData);
  const [showMailPopup, setShowMailPopup] = useState(false);
  const componentRef = useRef<HTMLDivElement>(null);

  // Print Handler
  const handlePrint = useReactToPrint({
    documentTitle: `Invoice-${invoiceData.invoiceNumber}`,
    // @ts-ignore - Type definition mismatch in react-to-print library
    content: () => componentRef.current,
    onBeforeGetContent: () => {
      // Ensure we're in preview mode before printing
      if (isEditMode) {
        setIsEditMode(false);
        // Return a promise to ensure the print waits for the state update
        return new Promise<void>((resolve) => {
          setTimeout(() => {
            resolve();
          }, 100);
        });
      }
      return Promise.resolve();
    },
    onAfterPrint: () => {
      console.log("Print completed successfully");
    },
  });

  // Download Handler (using PDFDownloadLink)
  const PdfLinkComponent = (
    <PDFDownloadLink
      document={<InvoicePDF invoiceData={invoiceData} />}
      fileName={`Invoice-${invoiceData.invoiceNumber}.pdf`}
      className="px-4 py-2 bg-green-500 text-white rounded hover:bg-green-600 transition duration-200 no-underline"
    >
      {/* @ts-ignore - Type definition mismatch in @react-pdf/renderer library */}
      {({ blob, url, loading, error }) =>
        loading ? "Loading PDF..." : "Download PDF"
      }
    </PDFDownloadLink>
  );

  // Send Mail Handler
  const handleSendMailClick = () => {
    setShowMailPopup(true);
  };

  const handleSendMailSubmit = (emails: string) => {
    console.log("Sending invoice to:", emails);
    // Here you would typically trigger a backend API call
    // For now, just log the emails
    alert(`Invoice would be sent to: ${emails}`);
  };

  // Edit Mode Toggle
  const toggleEditMode = () => {
    setIsEditMode(!isEditMode);
  };

  // Generate Invoice Number
  const generateInvoiceNumber = () => {
    const prefix = "INV";
    const randomDigits = Math.floor(10000 + Math.random() * 90000);
    const timestamp = new Date().getTime().toString().slice(-4);
    return `${prefix}-${randomDigits}-${timestamp}`;
  };

  // Generate Customer ID from customer info
  const generateCustomerId = (companyName: string, contactPerson: string) => {
    if (!companyName && !contactPerson) return "";

    // Use first 3 letters of company name (or first letter if shorter) + first letter of contact person
    const companyPrefix = companyName
      ? companyName.substring(0, Math.min(3, companyName.length)).toUpperCase()
      : "";
    const contactPrefix = contactPerson
      ? contactPerson.charAt(0).toUpperCase()
      : "";

    // Add a random 3-digit number
    const randomDigits = Math.floor(100 + Math.random() * 900);

    return `${companyPrefix}${contactPrefix}-${randomDigits}`;
  };

  // Form Submit Handler
  const handleFormSubmit = (data: InvoiceData) => {
    console.log("Invoice Form Submitted:", data);
    setInvoiceData(data);
    setIsEditMode(false); // Switch back to preview after submit
  };

  return (
    <div className="max-w-4xl mx-auto bg-white shadow-lg rounded-lg overflow-hidden my-8">
      {/* Action Buttons Area */}
      <div className="p-4 bg-gray-100 border-b flex flex-wrap justify-end gap-2">
        {!isEditMode && (
          <button
            onClick={handlePrint}
            className="px-4 py-2 bg-blue-500 text-white rounded hover:bg-blue-600 transition duration-200 text-sm"
          >
            Print
          </button>
        )}
        {!isEditMode && PdfLinkComponent}
        {!isEditMode && (
          <button
            onClick={handleSendMailClick}
            className="px-4 py-2 bg-yellow-500 text-white rounded hover:bg-yellow-600 transition duration-200 text-sm"
          >
            Send Via Mail
          </button>
        )}
        <button
          onClick={toggleEditMode}
          className="px-4 py-2 bg-purple-500 text-white rounded hover:bg-purple-600 transition duration-200 text-sm"
        >
          {isEditMode ? "Preview Mode" : "Edit Mode"}
        </button>
      </div>

      {/* Invoice Content Area */}
      <div ref={componentRef} className="invoice-content-area">
        {isEditMode ? (
          <InvoiceForm initialData={invoiceData} onSubmit={handleFormSubmit} />
        ) : (
          <InvoicePreview invoiceData={invoiceData} />
        )}
      </div>

      {/* Mail Popup */}
      {showMailPopup && (
        <SendMailPopup
          onClose={() => setShowMailPopup(false)}
          onSend={handleSendMailSubmit}
        />
      )}
    </div>
  );
};

export default InvoiceFour;

pages/InvoiceOne.tsx:
"use client";
import React, { useState, useRef } from "react";
import {
  PDFDownloadLink,
  Document,
  Page,
  Text,
  View,
  StyleSheet,
  Font,
  Image,
} from "@react-pdf/renderer";
import { useReactToPrint } from "react-to-print";

// Register font (you would need to load your actual font files)
Font.register({
  family: "Roboto",
  fonts: [
    {
      src: "https://fonts.gstatic.com/s/roboto/v30/KFOmCnqEu92Fr1Mu4mxP.ttf",
      fontWeight: 400,
    },
    {
      src: "https://fonts.gstatic.com/s/roboto/v30/KFOlCnqEu92Fr1MmEU9fBBc9.ttf",
      fontWeight: 700,
    },
  ],
});

// Define styles for PDF
const pdfStyles = StyleSheet.create({
  page: {
    fontFamily: "Roboto",
    padding: 40,
  },
  header: {
    flexDirection: "row",
    justifyContent: "space-between",
    marginBottom: 30,
  },
  logo: {
    fontSize: 24,
    fontWeight: "bold",
    marginBottom: 4,
  },
  slogan: {
    fontSize: 12,
    color: "#555",
  },
  invoiceTitle: {
    fontSize: 24,
    fontWeight: "bold",
    color: "#333",
  },
  section: {
    marginBottom: 20,
  },
  sectionTitle: {
    fontSize: 14,
    fontWeight: "bold",
    marginBottom: 8,
    borderBottomWidth: 1,
    borderBottomColor: "#eee",
    paddingBottom: 4,
  },
  row: {
    flexDirection: "row",
    justifyContent: "space-between",
    marginBottom: 8,
  },
  label: {
    fontSize: 10,
    color: "#777",
  },
  value: {
    fontSize: 10,
    fontWeight: "bold",
  },
  tableHeader: {
    flexDirection: "row",
    borderBottomWidth: 1,
    borderBottomColor: "#000",
    paddingBottom: 8,
    marginBottom: 8,
  },
  tableRow: {
    flexDirection: "row",
    borderBottomWidth: 1,
    borderBottomColor: "#eee",
    paddingBottom: 8,
    marginBottom: 8,
  },
  colNo: { width: "10%" },
  colDesc: { width: "40%" },
  colQty: { width: "15%", textAlign: "right" },
  colPrice: { width: "15%", textAlign: "right" },
  colTotal: { width: "20%", textAlign: "right" },
  totals: {
    flexDirection: "row",
    justifyContent: "flex-end",
    marginTop: 20,
  },
  totalsBox: {
    width: "40%",
  },
  totalRow: {
    flexDirection: "row",
    justifyContent: "space-between",
    marginBottom: 6,
  },
  grandTotal: {
    fontSize: 14,
    fontWeight: "bold",
    marginTop: 10,
    paddingTop: 10,
    borderTopWidth: 1,
    borderTopColor: "#000",
  },
  footer: {
    marginTop: 40,
    fontSize: 10,
    textAlign: "center",
    color: "#777",
  },
});

// PDF Document Component
const InvoicePDF = ({ invoiceData }: { invoiceData: InvoiceData }) => (
  <Document>
    <Page size="A4" style={pdfStyles.page}>
      <View style={pdfStyles.header}>
        <View>
          <Text style={pdfStyles.logo}>{invoiceData.logo}</Text>
          <Text style={pdfStyles.slogan}>{invoiceData.slogan}</Text>
        </View>
        <View>
          <Text style={pdfStyles.invoiceTitle}>INVOICE</Text>
        </View>
      </View>

      <View
        style={[
          pdfStyles.section,
          { flexDirection: "row", justifyContent: "space-between" },
        ]}
      >
        <View style={{ width: "48%" }}>
          <Text style={pdfStyles.sectionTitle}>Seller Information</Text>
          <Text style={pdfStyles.value}>{invoiceData.companyName}</Text>
          <Text style={pdfStyles.value}>{invoiceData.companyAddress}</Text>
          <Text style={pdfStyles.value}>Phone: {invoiceData.companyPhone}</Text>
          <Text style={pdfStyles.value}>Email: {invoiceData.companyEmail}</Text>
        </View>

        <View style={{ width: "48%" }}>
          <Text style={pdfStyles.sectionTitle}>Bill To</Text>
          <Text style={pdfStyles.value}>{invoiceData.clientCompanyName}</Text>
          <Text style={pdfStyles.value}>
            Attn: {invoiceData.clientContactPerson}
          </Text>
          <Text style={pdfStyles.value}>{invoiceData.clientLocation}</Text>
          <Text style={pdfStyles.value}>Phone: {invoiceData.clientPhone}</Text>
          <Text style={pdfStyles.value}>
            Due Date: {invoiceData.invoiceDueDate}
          </Text>
        </View>
      </View>

      <View style={pdfStyles.section}>
        <Text style={pdfStyles.sectionTitle}>Invoice Items</Text>
        <View style={pdfStyles.tableHeader}>
          <Text style={pdfStyles.colNo}>NO.</Text>
          <Text style={pdfStyles.colDesc}>PRODUCT/SERVICE</Text>
          <Text style={pdfStyles.colQty}>QTY</Text>
          <Text style={pdfStyles.colPrice}>UNIT PRICE</Text>
          <Text style={pdfStyles.colTotal}>TOTAL</Text>
        </View>

        {invoiceData.items.map((item, index) => (
          <View key={index} style={pdfStyles.tableRow}>
            <Text style={pdfStyles.colNo}>{index + 1}</Text>
            <Text style={pdfStyles.colDesc}>{item.description}</Text>
            <Text style={pdfStyles.colQty}>{item.quantity}</Text>
            <Text style={pdfStyles.colPrice}>
              $ {item.unitPrice.toFixed(2)}
            </Text>
            <Text style={pdfStyles.colTotal}>$ {item.amount.toFixed(2)}</Text>
          </View>
        ))}
      </View>

      <View style={pdfStyles.totals}>
        <View style={pdfStyles.totalsBox}>
          <View style={pdfStyles.totalRow}>
            <Text>Subtotal:</Text>
            <Text>$ {invoiceData.subtotal.toFixed(2)}</Text>
          </View>
          <View style={pdfStyles.totalRow}>
            <Text>Tax ({invoiceData.taxRate}%):</Text>
            <Text>$ {invoiceData.salesTax.toFixed(2)}</Text>
          </View>
          <View style={pdfStyles.totalRow}>
            <Text>Discount:</Text>
            <Text>$ 0.00</Text>
          </View>
          <View style={pdfStyles.grandTotal}>
            <Text>TOTAL DUE:</Text>
            <Text>$ {invoiceData.total.toFixed(2)}</Text>
          </View>
        </View>
      </View>

      <View style={pdfStyles.section}>
        <Text style={pdfStyles.sectionTitle}>Payment Information</Text>
        <Text>{invoiceData.paymentInstructions}</Text>
      </View>

      <View style={pdfStyles.footer}>
        <Text>{invoiceData.thankYouMessage}</Text>
        <Text>
          {invoiceData.companyName} | {invoiceData.companyAddress}
        </Text>
        <Text>
          Phone: {invoiceData.companyPhone} | Email: {invoiceData.companyEmail}
        </Text>
      </View>
    </Page>
  </Document>
);

interface InvoiceItem {
  description: string;
  quantity: number;
  unitPrice: number;
  taxable: boolean;
  amount: number;
}

interface InvoiceData {
  logo: string;
  slogan: string;
  companyName: string;
  companyAddress: string;
  companyPhone: string;
  companyEmail: string;
  clientContactPerson: string;
  clientCompanyName: string;
  clientLocation: string;
  clientPhone: string;
  invoiceDueDate: string;
  items: InvoiceItem[];
  subtotal: number;
  taxRate: number;
  salesTax: number;
  total: number;
  paymentInstructions: string;
  contactInstructions: string;
  thankYouMessage: string;
}

