                        #
                      </th>
                      <th className="px-4 py-2 text-left text-xs font-medium text-gray-500 uppercase tracking-wider">
                        Description
                      </th>
                      <th className="px-4 py-2 text-left text-xs font-medium text-gray-500 uppercase tracking-wider">
                        Qty
                      </th>
                      <th className="px-4 py-2 text-left text-xs font-medium text-gray-500 uppercase tracking-wider">
                        Unit Price
                      </th>
                      <th className="px-4 py-2 text-left text-xs font-medium text-gray-500 uppercase tracking-wider">
                        Taxable
                      </th>
                      <th className="px-4 py-2 text-left text-xs font-medium text-gray-500 uppercase tracking-wider">
                        Amount
                      </th>
                      <th className="px-4 py-2 text-left text-xs font-medium text-gray-500 uppercase tracking-wider">
                        Actions
                      </th>
                    </tr>
                  </thead>
                  <tbody className="bg-white divide-y divide-gray-200">
                    {invoiceData.items.map((item, index) => (
                      <tr key={index}>
                        <td className="px-4 py-2 whitespace-nowrap">
                          {index + 1}
                        </td>
                        <td className="px-4 py-2">
                          <input
                            type="text"
                            value={item.description}
                            onChange={(e) =>
                              handleItemChange(
                                index,
                                "description",
                                e.target.value
                              )
                            }
                            className="w-full p-1 border border-gray-300 rounded focus:ring-blue-500 focus:border-blue-500"
                          />
                        </td>
                        <td className="px-4 py-2">
                          <input
                            type="number"
                            value={item.quantity}
                            onChange={(e) =>
                              handleItemChange(
                                index,
                                "quantity",
                                e.target.value
                              )
                            }
                            min="1"
                            className="w-full p-1 border border-gray-300 rounded focus:ring-blue-500 focus:border-blue-500"
                          />
                        </td>
                        <td className="px-4 py-2">
                          <input
                            type="number"
                            value={item.unitPrice}
                            onChange={(e) =>
                              handleItemChange(
                                index,
                                "unitPrice",
                                e.target.value
                              )
                            }
                            className="w-full p-1 border border-gray-300 rounded focus:ring-blue-500 focus:border-blue-500"
                          />
                        </td>
                        <td className="px-4 py-2">
                          <input
                            type="checkbox"
                            checked={item.taxable}
                            onChange={(e) =>
                              handleItemChange(
                                index,
                                "taxable",
                                e.target.checked
                              )
                            }
                            className="h-4 w-4 text-blue-600 focus:ring-blue-500 border-gray-300 rounded"
                          />
                        </td>
                        <td className="px-4 py-2 whitespace-nowrap">
                          $ {item.amount.toFixed(2)}
                        </td>
                        <td className="px-4 py-2 whitespace-nowrap">
                          <button
                            onClick={() => removeItem(index)}
                            className="text-red-600 hover:text-red-800"
                          >
                            Remove
                          </button>
                        </td>
                      </tr>
                    ))}
                  </tbody>
                </table>
              </div>
            </div>

            {/* Totals Card */}
            <div className="bg-gray-50 p-4 rounded-lg mb-6">
              <h3 className="font-medium text-lg mb-3 text-gray-700">Totals</h3>
              <div className="grid grid-cols-1 md:grid-cols-3 gap-4">
                <div>
                  <label className="block text-sm font-medium text-gray-700 mb-1">
                    Tax Rate (%)
                  </label>
                  <input
                    type="number"
                    value={invoiceData.taxRate}
                    onChange={(e) => {
                      const taxRate = Number(e.target.value);
                      const salesTax = invoiceData.subtotal * (taxRate / 100);
                      setInvoiceData({
                        ...invoiceData,
                        taxRate,
                        salesTax,
                        total: invoiceData.subtotal + salesTax,
                      });
                    }}
                    className="w-full p-2 border border-gray-300 rounded focus:ring-blue-500 focus:border-blue-500"
                  />
                </div>
                <div>
                  <label className="block text-sm font-medium text-gray-700 mb-1">
                    Sales Tax ($)
                  </label>
                  <input
                    type="text"
                    value={invoiceData.salesTax.toFixed(2)}
                    readOnly
                    className="w-full p-2 border border-gray-300 rounded bg-gray-100"
                  />
                </div>
                <div>
                  <label className="block text-sm font-medium text-gray-700 mb-1">
                    Total ($)
                  </label>
                  <input
                    type="text"
                    value={invoiceData.total.toFixed(2)}
                    readOnly
                    className="w-full p-2 border border-gray-300 rounded bg-gray-100"
                  />
                </div>
              </div>
            </div>

            {/* Messages Card */}
            <div className="bg-gray-50 p-4 rounded-lg mb-6">
              <h3 className="font-medium text-lg mb-3 text-gray-700">
                Messages
              </h3>
              <div className="grid grid-cols-1 gap-4">
                <div>
                  <label className="block text-sm font-medium text-gray-700 mb-1">
                    Payment Instructions
                  </label>
                  <textarea
                    name="paymentInstructions"
                    value={invoiceData.paymentInstructions}
                    onChange={handleInputChange}
                    className="w-full p-2 border border-gray-300 rounded focus:ring-blue-500 focus:border-blue-500"
                    rows={2}
                  />
                </div>
                <div>
                  <label className="block text-sm font-medium text-gray-700 mb-1">
                    Contact Instructions
                  </label>
                  <textarea
                    name="contactInstructions"
                    value={invoiceData.contactInstructions}
                    onChange={handleInputChange}
                    className="w-full p-2 border border-gray-300 rounded focus:ring-blue-500 focus:border-blue-500"
                    rows={3}
                  />
                </div>
                <div>
                  <label className="block text-sm font-medium text-gray-700 mb-1">
                    Thank You Message
                  </label>
                  <input
                    type="text"
                    name="thankYouMessage"
                    value={invoiceData.thankYouMessage}
                    onChange={handleInputChange}
                    className="w-full p-2 border border-gray-300 rounded focus:ring-blue-500 focus:border-blue-500"
                  />
                </div>
              </div>
            </div>

            <div className="flex justify-end">
              <button
                onClick={submitForm}
                className="px-6 py-2 bg-blue-600 text-white rounded hover:bg-blue-700 transition"
              >
                Submit
              </button>
            </div>
          </div>
        ) : (
          <div ref={invoiceRef} className="bg-white p-8 rounded-lg shadow-md">
            <div className="mb-8">
              <div className="flex justify-between items-start">
                <div>
                  <h1 className="text-3xl font-bold text-gray-800">
                    {invoiceData.logo}
                  </h1>
                  <p className="text-gray-600">{invoiceData.slogan}</p>
                </div>
                <div className="text-right">
                  <h2 className="text-2xl font-bold text-gray-700 mb-4">
                    INVOICE
                  </h2>
                </div>
              </div>
            </div>

            <div className="grid grid-cols-1 md:grid-cols-2 gap-8 mb-8">
              <div>
                <h3 className="text-sm font-semibold text-gray-500 mb-2">
                  Seller Information
                </h3>
                <p className="font-medium">{invoiceData.companyName}</p>
                <p>{invoiceData.companyAddress}</p>
                <p>Phone: {invoiceData.companyPhone}</p>
                <p>Email: {invoiceData.companyEmail}</p>
              </div>

              <div className="bg-gray-50 p-4 rounded">
                <h3 className="text-sm font-semibold text-gray-500 mb-2">
                  Bill To
                </h3>
                <p>
                  <span className="font-medium">Company:</span>{" "}
                  {invoiceData.clientCompanyName}
                </p>
                <p>
                  <span className="font-medium">Attn:</span>{" "}
                  {invoiceData.clientContactPerson}
                </p>
                <p>
                  <span className="font-medium">Location:</span>{" "}
                  {invoiceData.clientLocation}
                </p>
                <p>
                  <span className="font-medium">Phone:</span>{" "}
                  {invoiceData.clientPhone}
                </p>
                <p className="mt-2">
                  <span className="font-medium">Due Date:</span>{" "}
                  {invoiceData.invoiceDueDate}
                </p>
              </div>
            </div>

            <div className="mb-8">
              <div className="border-t border-b border-gray-200 py-2">
                <h3 className="font-semibold">Invoice Items</h3>
              </div>
              <table className="w-full mt-4">
                <thead>
                  <tr className="border-b border-gray-200 text-left">
                    <th className="pb-2">NO.</th>
                    <th className="pb-2">PRODUCT/SERVICE</th>
                    <th className="pb-2 text-right">QTY</th>
                    <th className="pb-2 text-right">UNIT PRICE</th>
                    <th className="pb-2 text-right">TOTAL</th>
                  </tr>
                </thead>
                <tbody>
                  {invoiceData.items.map((item, index) => (
                    <tr key={index} className="border-b border-gray-100">
                      <td className="py-3">{index + 1}</td>
                      <td className="py-3">{item.description}</td>
                      <td className="text-right">{item.quantity}</td>
                      <td className="text-right">
                        $ {item.unitPrice.toFixed(2)}
                      </td>
                      <td className="text-right">$ {item.amount.toFixed(2)}</td>
                    </tr>
                  ))}
                </tbody>
              </table>
            </div>

            <div className="flex justify-end">
              <div className="w-64">
                <div className="flex justify-between py-2 border-b border-gray-200">
                  <span>Subtotal</span>
                  <span>$ {invoiceData.subtotal.toFixed(2)}</span>
                </div>
                <div className="flex justify-between py-2 border-b border-gray-200">
                  <span>Tax ({invoiceData.taxRate}%)</span>
                  <span>$ {invoiceData.salesTax.toFixed(2)}</span>
                </div>
                <div className="flex justify-between py-2 border-b border-gray-200">
                  <span>Discount</span>
                  <span>$ 0.00</span>
                </div>
                <div className="flex justify-between py-2 font-bold text-lg">
                  <span>TOTAL DUE</span>
                  <span>$ {invoiceData.total.toFixed(2)}</span>
                </div>
              </div>
            </div>

            <div className="mt-8 text-sm text-gray-600 whitespace-pre-line">
              <p className="font-medium mb-2">Payment Information:</p>
              <p>{invoiceData.paymentInstructions}</p>
              <p className="mt-4">{invoiceData.contactInstructions}</p>
            </div>

            <div className="mt-12 text-center text-gray-500">
              <p>{invoiceData.thankYouMessage}</p>
            </div>
          </div>
        )}
      </div>

      {/* Email Modal */}
      {showEmailModal && (
        <div className="fixed inset-0 bg-black bg-opacity-50 flex items-center justify-center p-4">
          <div className="bg-white rounded-lg p-6 w-full max-w-md">
            <h3 className="text-xl font-semibold mb-4">
              Send Invoice via Email
            </h3>
            <div className="mb-4">
              <label className="block text-sm text-gray-600 mb-2">
                Recipient Emails (comma separated)
              </label>
              <textarea
                value={emails}
                onChange={(e) => setEmails(e.target.value)}
                className="w-full p-2 border rounded"
                rows={4}
                placeholder="email1@example.com, email2@example.com"
              />
            </div>
            <div className="flex justify-end space-x-2">
              <button
                onClick={() => setShowEmailModal(false)}
                className="px-4 py-2 bg-gray-300 text-gray-700 rounded hover:bg-gray-400 transition"
              >
                Cancel
              </button>
              <button
                onClick={handleSendEmail}
                className="px-4 py-2 bg-blue-600 text-white rounded hover:bg-blue-700 transition"
              >
                Send
              </button>
            </div>
          </div>
        </div>
      )}
    </div>
  );
};

export default InvoiceOne;

pages/InvoiceThree.tsx:
"use client";
import React, { useState, useRef, useEffect } from "react";
import { useReactToPrint } from "react-to-print";
import html2canvas from "html2canvas";
import jsPDF from "jspdf";
interface InvoiceItem {
  id: string; // Unique ID for React keys and easier management
  quantity: number | "";
  description: string;
  unitPrice: number | "";
  taxable: boolean;
  amount: number;
}

// Define the overall structure for invoice data
interface InvoiceData {
  company: {
    name: string;
    address: string;
    phone: string;
    email: string;
    logoUrl: string; // Added for company logo
  };
  invoiceDetails: {
    date: string;
    invoiceNumber: string;
    customerID: string;
    preparedBy: string;
    invoiceDueDate: string;
  };
  billTo: {
    contactPerson: string;
    companyName: string;
    location: string;
    phone: string;
  };
  items: InvoiceItem[];
  subtotal: number;
  taxRate: number; // Stored as a percentage (e.g., 0.05 for 5%)
  salesTax: number;
  other: number;
  total: number;
  notes: string;
  paymentInfo: string;
  thankYouMessage: string;
}

// Initial dummy data for the invoice
const initialInvoiceData: InvoiceData = {
  company: {
