    minimumFractionDigits: 2,
  }).format(value);
};

// Invoice Preview Component
const InvoicePreview: React.FC<{ invoice: InvoiceData }> = ({ invoice }) => {
  return (
    <div className="bg-white p-8 rounded-lg shadow-xl max-w-4xl mx-auto my-8 font-inter">
