product-details/ProductDetailEight.tsx:
"use client";
// ProductDetail.tsx
import React, { useState } from "react";
import Image from "next/image";
import Link from "next/link";
import {
  StarIcon,
  MinusIcon,
  PlusIcon,
  XMarkIcon,
  MapPinIcon,
  ShieldCheckIcon,
  TruckIcon,
} from "@heroicons/react/24/outline";
import { StarIcon as StarSolidIcon } from "@heroicons/react/24/solid";

interface ProductImage {
  id: number;
  url: string;
  alt: string;
}

interface ProductColor {
  name: string;
  value: string;
}

interface ProductSize {
  name: string;
  available: boolean;
}

interface ProductReview {
  rating: number;
  count: number;
  totalReviews: number;
}

interface ProductDetails {
  id: string;
  name: string;
  description: string;
  price: number;
