        <div className="max-w-7xl mx-auto px-4 sm:px-6 lg:px-8">
          <div className="flex justify-between h-16 items-center">
            <div className="flex items-center">
              <div className="flex-shrink-0">
                <span className="text-xl font-bold text-gray-900">
                  lulu<span className="font-normal">andgeorgia</span>
                </span>
              </div>
            </div>

            <nav className="hidden md:flex space-x-8">
              <a href="#" className="text-sm text-gray-500 hover:text-gray-900">
                About Us
              </a>
              <a href="#" className="text-sm text-gray-500 hover:text-gray-900">
                Our Collections
              </a>
              <a href="#" className="text-sm text-gray-500 hover:text-gray-900">
                Design Inspiration
              </a>
              <a href="#" className="text-sm text-gray-500 hover:text-gray-900">
                Our Projects
              </a>
            </nav>

            <div className="flex items-center space-x-4">
              <button className="text-gray-500 hover:text-gray-900">
                <Search className="h-5 w-5" />
              </button>
              <button className="text-gray-500 hover:text-gray-900">
                <ShoppingCart className="h-5 w-5" />
              </button>
            </div>
          </div>
        </div>
      </header>

      {/* Product Detail Section */}
      <main className="max-w-7xl mx-auto px-4 sm:px-6 lg:px-8 py-8">
        <div className="grid grid-cols-1 lg:grid-cols-12 gap-12">
          {/* Product Images Column */}
          <div className="lg:col-span-7">
            <div className="flex flex-row">
              {/* Thumbnails */}
              <div className="flex flex-col mr-4 space-y-4">
                {product.images.map((image, index) => (
                  <button
                    key={image.id}
                    onClick={() => setActiveImage(index)}
                    className={`w-16 h-16 border ${
                      activeImage === index
                        ? "border-gray-900"
                        : "border-gray-200"
                    }`}
                  >
                    <div className="relative w-full h-full overflow-hidden">
                      <Image
                        src={image.thumbnail}
                        alt={image.alt}
                        fill
                        className="object-cover"
                        sizes="64px"
                      />
                    </div>
                  </button>
                ))}
              </div>

              {/* Main Image */}
              <div className="flex-1 bg-gray-100">
                <div className="relative aspect-square overflow-hidden">
                  <Image
                    src={product.images[activeImage].src}
                    alt={product.images[activeImage].alt}
                    fill
                    className="object-cover"
                    sizes="(max-width: 1024px) 100vw, 50vw"
                    priority
                  />
                </div>
              </div>
            </div>
          </div>

          {/* Product Info Column */}
          <div className="lg:col-span-5">
            <h1 className="text-3xl font-medium text-gray-900">
              {product.name}
            </h1>
            <p className="mt-1 text-sm text-gray-600">by {product.designer}</p>

            <p className="mt-4 text-2xl font-medium">
              {formatPrice(product.price)}
            </p>
            <button className="mt-2 text-sm text-gray-600 hover:text-gray-900 underline">
              Request Free Swatch
            </button>

            {/* Color Options */}
            <div className="mt-6 flex space-x-2">
              {product.colors.map((color, index) => (
                <button
                  key={color.id}
                  onClick={() => setSelectedColor(index)}
                  className={`w-8 h-8 border ${
                    selectedColor === index
                      ? "border-gray-900"
                      : "border-gray-300"
                  }`}
                  title={color.name}
                >
                  <span
                    className="block w-full h-full"
                    style={{ backgroundColor: color.value }}
                  ></span>
                </button>
              ))}
            </div>

            {/* Quantity Selector */}
            <div className="mt-6 flex items-center">
              <button
                onClick={() => setQuantity(Math.max(1, quantity - 1))}
                className="p-2 border border-gray-300 text-gray-600"
              >
                <Minus className="h-4 w-4" />
              </button>
              <span className="w-10 text-center">{quantity}</span>
              <button
                onClick={() => setQuantity(quantity + 1)}
                className="p-2 border border-gray-300 text-gray-600"
              >
                <Plus className="h-4 w-4" />
              </button>
              <span className="ml-auto text-sm text-gray-600">
                ${(product.price * quantity).toFixed(2)}
              </span>
            </div>

            {/* CTAs */}
            <div className="mt-6 grid grid-cols-2 gap-4">
              <button className="py-3 px-4 border border-gray-900 text-gray-900 font-medium">
                BUY NOW
              </button>
              <button className="py-3 px-4 bg-gray-900 text-white font-medium">
                ADD TO CART
              </button>
            </div>

            {/* Product Description */}
            <div className="mt-8">
              <p className="text-sm text-gray-600 leading-relaxed">
                {product.description}
              </p>
            </div>

            {/* Accordion Sections */}
            <div className="mt-8 border-t border-gray-200">
              {/* Details Section */}
              <div className="py-4 border-b border-gray-200">
                <button
                  onClick={() => toggleAccordion("details")}
                  className="flex justify-between items-center w-full text-left"
                >
                  <span className="text-sm font-medium text-gray-900">
                    Details
                  </span>
                  <Plus
                    className={`h-4 w-4 text-gray-500 transition-transform ${
                      activeAccordion === "details" ? "rotate-45" : ""
                    }`}
                  />
                </button>
                {activeAccordion === "details" && (
                  <div className="mt-4 text-sm text-gray-600">
                    <p>{product.details}</p>
                  </div>
                )}
              </div>

              {/* Dimensions Section */}
              <div className="py-4 border-b border-gray-200">
                <button
                  onClick={() => toggleAccordion("dimensions")}
                  className="flex justify-between items-center w-full text-left"
                >
                  <span className="text-sm font-medium text-gray-900">
                    Dimensions
                  </span>
                  <Plus
                    className={`h-4 w-4 text-gray-500 transition-transform ${
                      activeAccordion === "dimensions" ? "rotate-45" : ""
                    }`}
                  />
                </button>
                {activeAccordion === "dimensions" && (
                  <div className="mt-4 grid grid-cols-2 gap-2 text-sm text-gray-600">
                    <p>Width: {product.dimensions.width}</p>
                    <p>Depth: {product.dimensions.depth}</p>
                    <p>Height: {product.dimensions.height}</p>
                    {product.dimensions.seatHeight && (
                      <p>Seat Height: {product.dimensions.seatHeight}</p>
                    )}
                    {product.dimensions.weight && (
                      <p>Weight: {product.dimensions.weight}</p>
                    )}
                  </div>
                )}
              </div>

              {/* Care Section */}
              <div className="py-4 border-b border-gray-200">
                <button
                  onClick={() => toggleAccordion("care")}
                  className="flex justify-between items-center w-full text-left"
                >
                  <span className="text-sm font-medium text-gray-900">
                    Care
                  </span>
                  <Plus
                    className={`h-4 w-4 text-gray-500 transition-transform ${
                      activeAccordion === "care" ? "rotate-45" : ""
                    }`}
                  />
                </button>
                {activeAccordion === "care" && (
                  <div className="mt-4 text-sm text-gray-600">
                    <p>{product.care}</p>
                  </div>
                )}
              </div>

              {/* Sustainability Section */}
              <div className="py-4 border-b border-gray-200">
                <button
                  onClick={() => toggleAccordion("sustainability")}
                  className="flex justify-between items-center w-full text-left"
                >
                  <span className="text-sm font-medium text-gray-900">
                    Sustainability
                  </span>
                  <Plus
                    className={`h-4 w-4 text-gray-500 transition-transform ${
                      activeAccordion === "sustainability" ? "rotate-45" : ""
                    }`}
                  />
                </button>
                {activeAccordion === "sustainability" && (
                  <div className="mt-4 text-sm text-gray-600">
                    <p>{product.sustainability}</p>
                  </div>
                )}
              </div>
            </div>
          </div>
        </div>
      </main>

      {/* Instagram Section */}
      <InstagramSection hashtag="LANDGATHOME" posts={instagramPosts} />

      {/* Recently Viewed Section */}
      <div className="border-t border-gray-200">
        <RecommendedProducts
          title="Recently Viewed"
          products={recentlyViewed}
        />
      </div>

      {/* Recommended Products Section */}
      <RecommendedProducts
        title="Most Recommended Product For You!"
        products={recommended}
      />

      {/* Footer Get In Touch Section */}
      <FooterGetInTouch shippingInfo={shippingInfo} socialMedia={socialMedia} />
    </div>
  );
};

export default ProductDetailSix;

import { ChevronLeft, ChevronRight } from "lucide-react";

interface RecommendedProduct {
  id: string;
  name: string;
  price: number;
  image: string;
  designer: string;
  tag?: "Exclusive" | "Best Seller" | "New";
}

interface RecommendedProductsProps {
  title: string;
  products: RecommendedProduct[];
}

const RecommendedProducts = ({ title, products }: RecommendedProductsProps) => {
  const [activeSlide, setActiveSlide] = useState(0);

  // Format price
  const formatPrice = (price: number) => {
    return new Intl.NumberFormat("en-US", {
      style: "currency",
      currency: "USD",
      minimumFractionDigits: 0,
      maximumFractionDigits: 0,
    }).format(price);
  };

  return (
    <section className="py-12">
      <div className="max-w-7xl mx-auto px-4 sm:px-6 lg:px-8">
        <h2 className="text-2xl font-bold text-gray-900 mb-8 text-center">
          {title}
        </h2>

        <div className="relative">
          <div className="grid grid-cols-1 md:grid-cols-3 gap-8">
            {products.map((product) => (
              <div key={product.id} className="group">
                <div className="relative aspect-square overflow-hidden bg-gray-100">
                  {product.tag && (
                    <div className="absolute top-2 left-2 z-10">
                      <span
                        className={`
                        inline-block px-2 py-1 text-xs font-medium
                        ${
                          product.tag === "Exclusive"
                            ? "bg-yellow-100 text-yellow-800"
                            : product.tag === "Best Seller"
                            ? "bg-blue-100 text-blue-800"
                            : "bg-green-100 text-green-800"
                        }
                      `}
                      >
                        {product.tag}
                      </span>
                    </div>
                  )}
                  <Image
                    src={product.image}
                    alt={product.name}
                    fill
                    className="object-cover transition-transform duration-300 group-hover:scale-105"
                    sizes="(max-width: 768px) 100vw, 33vw"
                  />
                </div>
                <div className="mt-4">
                  <h3 className="text-base font-medium text-gray-900">
                    {product.name}
                  </h3>
                  <p className="mt-1 text-sm text-gray-500">
                    By {product.designer}
                  </p>
                  <p className="mt-1 font-medium text-gray-900">
                    {formatPrice(product.price)}
                  </p>
                </div>
              </div>
            ))}
          </div>

          <div className="absolute top-1/2 left-0 transform -translate-y-1/2">
            <button className="p-2 bg-white rounded-full shadow-md">
              <ChevronLeft className="h-5 w-5 text-gray-600" />
            </button>
          </div>
          <div className="absolute top-1/2 right-0 transform -translate-y-1/2">
            <button className="p-2 bg-white rounded-full shadow-md">
              <ChevronRight className="h-5 w-5 text-gray-600" />
            </button>
          </div>
        </div>

        <div className="flex justify-center mt-6 space-x-2">
          {[0, 1, 2, 3].map((_, index) => (
            <button
              key={index}
              className={`w-2 h-2 rounded-full ${
                activeSlide === index ? "bg-gray-900" : "bg-gray-300"
              }`}
              onClick={() => setActiveSlide(index)}
            ></button>
          ))}
        </div>
      </div>
    </section>
  );
};

interface InstagramPost {
  id: string;
  image: string;
  alt: string;
}

interface InstagramSectionProps {
