  const scroll = (direction: "left" | "right") => {
    if (isAnimating || !carouselRef.current) return;

    setIsAnimating(true);

    const container = carouselRef.current;
    const scrollAmount =
      direction === "left"
        ? container.scrollLeft - container.offsetWidth
        : container.scrollLeft + container.offsetWidth;

