  },
];

interface MobileLinkProps {
  href: string;
  onOpenChange?: (open: boolean) => void;
  className?: string;
  children: React.ReactNode;
  [key: string]: any;
}

function MobileLink({
  href,
  onOpenChange,
  className,
  children,
  ...props
}: MobileLinkProps) {
  const router = useRouter();
  return (
    <Link
      href={href}
      onClick={() => {
        router.push(href.toString());
        onOpenChange?.(false);
      }}
      className={cn(className)}
      {...props}
    >
      {children}
    </Link>
  );
}

interface MobileNavBarProps {
  categories?: Category[];
}

