}

function Logo(): JSX.Element {
  return (
    <Link href="/" className="flex items-center gap-2">
      {/* <div className="relative w-12 h-12 overflow-hidden">
        <Image
          src="/logo.svg"
          alt="KYAJA"
          width={48}
          height={48}
          className="object-contain"
        />
