          <DropdownMenuItem>Home & Kitchen</DropdownMenuItem>
          <DropdownMenuItem>Clothing</DropdownMenuItem>
          <DropdownMenuItem>Beauty</DropdownMenuItem>
        </DropdownMenuContent>
