          }`}
        />

        {/* Time Left Badge */}
        {deal.timeLeft && (
          <div className="absolute bottom-2 right-2">
            <span className="bg-orange-500 text-white text-xs font-bold px-2 py-1 rounded flex items-center gap-1">
