              }}
            />
          </div>
        )}

        {/* Add to Cart Button */}
        <Button
          className="w-full bg-red-600 hover:bg-red-700 text-white font-medium py-2 rounded text-sm transition-colors duration-200"
          size="sm"
        >
          <ShoppingBag className="h-4 w-4 mr-2" />
          Add to Cart
        </Button>
      </div>
    </Card>
  );
}

export default function ProductEleven() {
