            </Button>
          </div>
        </div>

        {/* Deals Grid */}
        <div className="bg-white p-6 rounded-b-lg shadow-lg">
          <div className="grid grid-cols-1 md:grid-cols-2 lg:grid-cols-3 gap-6">
            {todaysDeals.map((deal) => (
